recipes.code:
{
  "inputs": [
    {
      "id": "mcp-api-key",
      "type": "promptString",
      "description": "Your MetricSpot API key (ms_live_...) from app.metricspot.com/settings/api-keys. Required for 5 of the 6 tools; omit to use only run_audit_anonymous (1 audit per IP per 24 hours, no auth).",
      "password": true
    }
  ],
  "servers": {
    "seo": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@metricspot/mcp-server@0.1.1"
      ],
      "env": {
        "MCP_API_KEY": "${input:mcp-api-key}"
      }
    }
  }
}
